<?php
declare(strict_types=1);
use Gyugyu\{Database,Schedules,Confirmation,Participants,Groups,Days,Export};
$db=Database::connect(':memory:');Database::migrate($db);$s=new Schedules($db);$c=new Confirmation($db);$p=new Participants($db);$g=new Groups($db);$d=new Days($db);
$r=$s->create(['title'=>'=確定','dates'=>['2026-11-01','2026-11-02']]);$id=$r['id'];$slot=$r['days'][0]['slots'][6]['id'];
$rev=fn()=>['expected_version'=>$s->get($id)['version'],'expected_schema_revision'=>$s->get($id)['schema_revision'],'expected_answers_revision'=>$s->get($id)['answers_revision']];
$a=$g->change($id,null,'create',$rev()+['name'=>'<群A>']);$b=$g->change($id,null,'create',$rev()+['name'=>'群B']);
$one=$p->submit($id,null,$rev()+['display_name'=>'同名','submission_key'=>str_repeat('a',32),'group_ids'=>[$a['id'],$b['id']],'answers'=>[['slot_id'=>$slot,'state'=>'no']]]);
$two=$p->submit($id,null,$rev()+['display_name'=>'同名','submission_key'=>str_repeat('b',32),'group_ids'=>[$b['id']],'answers'=>[]]);
$req=$rev()+['slot_id'=>$slot,'mode'=>'include','group_ids'=>[$a['id'],$b['id']],'confirmation'=>'=確定','confirm_selection'=>true];
$before=$s->get($id);$preview=$c->change($id,'confirm',$req,true);check($s->get($id)===$before,'decision preview is DB invariant');
check($preview['decision']['mask']['N']===2&&count($preview['decision']['mask']['participant_ids'])===2,'mask OR deduplicates same-name stable IDs');check($preview['decision']['mask']['counts']['no']===1&&$preview['decision']['mask']['counts']['unknown']===1,'negative and unknown remain eligible');
foreach(['expected_version','expected_schema_revision','expected_answers_revision'] as $key){rejects(fn()=>$c->change($id,'confirm',array_replace($req,[$key=>0])),409);rejects(fn()=>$c->change($id,'confirm',array_replace($req,[$key=>(string)$req[$key]])),409);}
foreach([['confirmation'=>'wrong'],['confirm_selection'=>false],['slot_id'=>$r['days'][0]['slots'][0]['id']],['mode'=>'bad'],['group_ids'=>['foreign']]] as $patch)rejects(fn()=>$c->change($id,'confirm',array_replace($req,$patch)),422);
rejects(fn()=>$c->change($id,'confirm',$req+['participant_ids'=>[$one['id']]]),422);
$foreign=$s->create(['title'=>'別','dates'=>['2026-11-01']]);rejects(fn()=>$c->change($id,'confirm',array_replace($req,['slot_id'=>$foreign['days'][0]['slots'][6]['id']])),422);
$two=$p->submit($id,$two['id'],$rev()+['expected_participant_version'=>1,'display_name'=>'同名','answers'=>[]]);rejects(fn()=>$c->change($id,'confirm',$req),409);
$req=array_replace($req,$rev());$g->change($id,$a['id'],'edit',$rev()+['expected_group_version'=>1,'name'=>'改名A']);rejects(fn()=>$c->change($id,'confirm',$req),409);$req=array_replace($req,$rev());
dateCommit($d,$id,'archive',['expected_version'=>1,'expected_schema_revision'=>$s->get($id)['schema_revision'],'day_id'=>$r['days'][1]['id']]);$req=array_replace($req,$rev());rejects(fn()=>$c->change($id,'confirm',array_replace($req,['slot_id'=>$r['days'][1]['slots'][6]['id']])),422);
$db->exec("CREATE TRIGGER fail_confirmation BEFORE INSERT ON audit_log WHEN NEW.action LIKE 'decision-%' BEGIN SELECT RAISE(ABORT,'fixture'); END");$before=$s->get($id);
try{$c->change($id,'confirm',$req);throw new RuntimeException('missing rollback');}catch(PDOException $e){}check($s->get($id)===$before&&$c->current($id)===null,'confirmation and status rollback on audit failure');$db->exec('DROP TRIGGER fail_confirmation');
$confirmed=$c->change($id,'confirm',$req);$decision=$confirmed['confirmation'];check($confirmed['status']==='confirmed'&&$confirmed['version']===2,'confirm increments instance version');check($confirmed['schema_revision']===$before['schema_revision']&&$confirmed['answers_revision']===$before['answers_revision'],'decision does not change answer/schema revisions');
check($decision['slot_id']===$slot&&$decision['starts_at_utc']==='2026-11-01T00:00:00Z'&&$decision['ends_at_utc']==='2026-11-01T00:30:00Z'&&is_string($decision['confirmed_at']),'fixed slot UTC bounds and decision timestamp');
check($decision['mask']['participants'][0]['id']!==$decision['mask']['participants'][1]['id']&&$decision['mask']['groups'][0]['name']==='改名A','snapshot stores IDs and historical labels');
rejects(fn()=>$c->change($id,'confirm',$req),409);foreach(['lock','reopen'] as $action)rejects(fn()=>$s->reception($id,$rev()+['action'=>$action,'confirmation'=>'=確定']),409);
$json=json_decode((new Export($db))->generate($id,[])['content'],true);check($json['instance']['confirmation']===$decision,'full JSON retains exact current decision snapshot');
$csv=csvRows((new Export($db))->generate($id,['format'=>'wide','scope'=>'mask','mode'=>'exclude','group_ids'=>[$a['id']]])['content']);$line=array_combine($csv[0],$csv[1]);check($line['confirmed_slot_id']===$slot&&json_decode($line['confirmed_mask_json'],true)===$decision['mask'],'CSV view mask never replaces frozen mask');check($c->current($id)===$decision,'export filters do not mutate decision');
try{$db->exec("UPDATE instance_confirmations SET slot_id=slot_id");throw new RuntimeException('immutable missing');}catch(PDOException $e){check(true,'decision row immutable');}
$s->change($id,'delete',['expected_version'=>2,'confirmation'=>'=確定']);rejects(fn()=>$c->change($id,'cancel',['expected_version'=>3]),404);$restored=$s->change($id,'restore',['expected_version'=>3]);check($restored['status']==='confirmed'&&$restored['confirmation']===$decision,'confirmed delete/restore preserves complete details');
$cancel=$rev()+['confirmation'=>'=確定','confirm_selection'=>true];$db->exec("CREATE TRIGGER fail_cancel BEFORE INSERT ON audit_log WHEN NEW.action='decision-cancel' BEGIN SELECT RAISE(ABORT,'fixture'); END");try{$c->change($id,'cancel',$cancel);throw new RuntimeException('missing rollback');}catch(PDOException $e){}check($c->current($id)===$decision&&$s->get($id)['status']==='confirmed','cancel audit failure restores current decision');$db->exec('DROP TRIGGER fail_cancel');
$open=$c->change($id,'cancel',$cancel);check($open['status']==='open'&&$open['confirmation']===null,'cancel clears current decision and opens');$audit=json_decode($db->query("SELECT summary_json FROM audit_log WHERE action='decision-cancel' ORDER BY id DESC LIMIT 1")->fetchColumn(),true);check($audit['decision']===$decision,'cancel audit preserves complete prior decision');rejects(fn()=>$c->change($id,'cancel',$cancel),409);
// Explicitly zero targets allowed; lock-origin cancel returns open, not locked.
$s->reception($id,$rev()+['action'=>'lock','confirmation'=>'=確定']);$zero=$c->change($id,'confirm',$rev()+['slot_id'=>$slot,'mode'=>'include','group_ids'=>[],'confirmation'=>'=確定','confirm_selection'=>true]);check($zero['confirmation']['mask']['N']===0&&$zero['confirmation']['mask']['score']===null,'zero-target confirm permitted from locked');$c->change($id,'cancel',$rev()+['confirmation'=>'=確定','confirm_selection'=>true]);check($s->get($id)['status']==='open','cancel locked-origin decision returns open');
// No groups + no people permits a selected candidate, but absent candidates never do.
$empty=$s->create(['title'=>'空','dates'=>['2026-11-01']]);$er=['expected_version'=>1,'expected_schema_revision'=>1,'expected_answers_revision'=>$empty['answers_revision'],'slot_id'=>$empty['days'][0]['slots'][6]['id'],'mode'=>'include','group_ids'=>[],'confirmation'=>'空','confirm_selection'=>true];$ec=$c->change($empty['id'],'confirm',$er);check($ec['confirmation']['mask']['mode']==='all'&&$ec['confirmation']['mask']['N']===0,'zero-group mask resolves all with zero participants');
$c->change($empty['id'],'cancel',['expected_version'=>2,'expected_schema_revision'=>1,'expected_answers_revision'=>$empty['answers_revision'],'confirmation'=>'空','confirm_selection'=>true]);
$db->prepare('UPDATE day_slots SET is_candidate=0 WHERE day_id=?')->execute([$empty['days'][0]['id']]);rejects(fn()=>$c->change($empty['id'],'confirm',array_replace($er,['expected_version'=>3])),422);
$db->prepare("UPDATE instance_days SET archived_at='fixture' WHERE id=?")->execute([$empty['days'][0]['id']]);rejects(fn()=>$c->change($empty['id'],'confirm',array_replace($er,['expected_version'=>3])),422);
// Upgrade existing data without inventing a decision for old confirmed fixtures.
$old=Database::connect(':memory:');foreach(['001_initial.sql','002_participants.sql','003_groups.sql'] as $file)$old->exec(file_get_contents(dirname(__DIR__).'/database/migrations/'.$file));$old->exec("CREATE TABLE migrations(name TEXT PRIMARY KEY);INSERT INTO migrations VALUES ('001_initial.sql'),('002_participants.sql'),('003_groups.sql')");$old->exec("INSERT INTO instances(id,title,created_at,updated_at) VALUES ('legacy','既存','2020-01-01T00:00:00Z','2020-01-01T00:00:00Z')");$oldBefore=$old->query('SELECT * FROM instances')->fetchAll();Database::migrate($old);Database::migrate($old);check($old->query('SELECT * FROM instances')->fetchAll()===$oldBefore,'migration preserves pre-existing instance rows');check($old->query('SELECT COUNT(*) FROM migrations')->fetchColumn()===4,'old schema upgrades idempotently');
$legacy=(new Schedules($old))->create(['title'=>'旧','dates'=>['2026-11-01']]);$old->prepare("UPDATE instances SET status='confirmed' WHERE id=?")->execute([$legacy['id']]);$legacyOpen=(new Confirmation($old))->change($legacy['id'],'cancel',['expected_version'=>1,'expected_schema_revision'=>1,'expected_answers_revision'=>$legacy['answers_revision'],'confirmation'=>'旧','confirm_selection'=>true]);check($legacyOpen['status']==='open'&&$legacyOpen['confirmation']===null,'legacy missing decision explicit cancel does not fabricate history');
check($db->query('PRAGMA foreign_key_check')->fetchAll()===[],'confirmation references consistent');

$next=$c->change($id,'confirm',$rev()+['slot_id'=>$slot,'mode'=>'exclude','group_ids'=>[],'confirmation'=>'=確定','confirm_selection'=>true]);
$backup=tempnam(sys_get_temp_dir(),'gyugyu-decision-');unlink($backup);
try {$db->exec('VACUUM INTO '.$db->quote($backup));$copy=Database::connect($backup);Database::migrate($copy);check((new Schedules($copy))->get($id)['confirmation']===$next['confirmation'],'backup restores decision and frozen mask');$copy=null;}
finally {foreach([$backup,$backup.'-wal',$backup.'-shm'] as $file)if(is_file($file))unlink($file);}
